begin;
create temporary table rider_int_results(name text,pass boolean);
create function pg_temp.check_int(n text,v boolean) returns void language plpgsql as $$begin if not coalesce(v,false) then raise exception 'FAIL: %',n;end if;insert into rider_int_results values(n,true);end $$;
create function pg_temp.int_cmd(u uuid,a text,op text,p jsonb default '{}') returns jsonb language plpgsql as $$declare r int;begin select revision into r from lx_rider_private.workspaces where owner_id=u;return lx_rider_private.gateway(u,op,p||jsonb_build_object('actor',a,'revision',r,'command_id',gen_random_uuid()));end $$;
create function pg_temp.int_denied(u uuid,a text,op text,p jsonb,msg text) returns boolean language plpgsql as $$begin perform pg_temp.int_cmd(u,a,op,p);return false;exception when others then return sqlerrm=msg;end $$;
do $$
declare u uuid;b uuid;w uuid;v uuid;t uuid;ids uuid[]:='{}';code text;object_path text;before_count int;after_count int;req jsonb;r jsonb;rev int;cid uuid;
begin
 select id into u from auth.users where lx_share_private.test_member(id) order by id limit 1;
 select id into b from auth.users where lx_share_private.test_member(id) order by id offset 1 limit 1;
 select count(*) into before_count from public.lx_share_bags;
 perform lx_rider_private.gateway(u,'initialize','{}');perform lx_rider_private.gateway(b,'initialize','{}');
 select id into w from lx_rider_private.workspaces where owner_id=u;
 update lx_rider_private.people set application='approved',license_status='approved',cert_valid_until=current_date+365,simulation_confirmed=true where workspace_id=w and key='rider1';
 insert into lx_rider_private.vehicles(workspace_id,rider_key,label,status,owner_authorized) values(w,'rider1','TEST-CAP','approved',true) returning id into v;
 for i in 1..4 loop
 insert into lx_rider_private.tasks(workspace_id,bag_code,pickup_label,delivery_label,pickup_lat,pickup_lng,delivery_lat,delivery_lng) values(w,'TEST-CAP-'||gen_random_uuid()::text,'模擬取件','模擬交付',22.99,120.2,23,120.21) returning id into t;
 ids:=array_append(ids,t);
 end loop;
 perform pg_temp.check_int('pool summary hides coordinates',not exists(select 1 from jsonb_array_elements(lx_rider_private.snapshot(w,'rider1')->'available_tasks') x where x ? 'pickup_lat' or x ? 'pickup_lng' or x ? 'delivery_lat' or x ? 'pickup_label' or x ? 'pickup_photo_path'));
 perform pg_temp.check_int('other workspace cannot claim',pg_temp.int_denied(b,'rider1','claim',jsonb_build_object('task_id',ids[1],'vehicle_id',v),'RIDER_TASK_DENIED'));
 perform pg_temp.check_int('receiver cannot claim',pg_temp.int_denied(u,'receiver','claim',jsonb_build_object('task_id',ids[1],'vehicle_id',v),'RIDER_ROLE_DENIED'));
 for i in 1..3 loop perform pg_temp.int_cmd(u,'rider1','claim',jsonb_build_object('task_id',ids[i],'vehicle_id',v));end loop;
 perform pg_temp.check_int('three pool claims succeed',(select count(*)=3 from lx_rider_private.tasks where id=any(ids) and status='accepted'));
 perform pg_temp.check_int('fourth claim is blocked',pg_temp.int_denied(u,'rider1','claim',jsonb_build_object('task_id',ids[4],'vehicle_id',v),'RIDER_CAPACITY_REACHED'));
 perform pg_temp.check_int('other rider cannot claim taken task',pg_temp.int_denied(u,'rider2','claim',jsonb_build_object('task_id',ids[1],'vehicle_id',v),'RIDER_TASK_DENIED'));
 perform pg_temp.int_cmd(u,'rider1','arrive',jsonb_build_object('task_id',ids[1]));
 perform pg_temp.check_int('arrival timestamp persists',(select arrived_at is not null from lx_rider_private.tasks where id=ids[1]));
 select bag_code into code from lx_rider_private.tasks where id=ids[1];
 perform pg_temp.check_int('missing proof object rejected when referenced',pg_temp.int_denied(u,'rider1','pickup',jsonb_build_object('task_id',ids[1],'bag_code',code,'sealed',true,'photo_path','missing.webp'),'RIDER_PHOTO_INVALID'));
 -- Internal service fixture transitions do not represent user Edge/photo acceptance.
 perform pg_temp.int_cmd(u,'rider1','pickup',jsonb_build_object('task_id',ids[1],'bag_code',code,'sealed',true));
 perform pg_temp.int_cmd(u,'rider1','handover',jsonb_build_object('task_id',ids[1]));
 perform pg_temp.check_int('pending receiver keeps unsigned handover record',(select status='handover_pending' and received_at is null and receipt_code is null from lx_rider_private.tasks where id=ids[1]));
 select revision into rev from lx_rider_private.workspaces where id=w;cid:=gen_random_uuid();req:=jsonb_build_object('actor','rider1','task_id',ids[4],'vehicle_id',v,'revision',rev,'command_id',cid);
 r:=lx_rider_private.gateway(u,'claim',req);
 perform pg_temp.check_int('handover releases slot before receiver signature',(select status='accepted' from lx_rider_private.tasks where id=ids[4]));
 perform pg_temp.check_int('duplicate claim command returns same result',lx_rider_private.gateway(u,'claim',req)=r);
 perform pg_temp.int_cmd(u,'receiver','receive',jsonb_build_object('task_id',ids[1],'bag_code',code));
 perform pg_temp.check_int('completed task stays in history',exists(select 1 from jsonb_array_elements(lx_rider_private.snapshot(w,'rider1')->'tasks') x where x->>'id'=ids[1]::text and x->>'status'='delivered'));
 object_path:=u::text||'/'||w::text||'/'||ids[4]::text||'/rider1/pickup/image/'||gen_random_uuid()::text||'.webp';
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform pg_temp.check_int('own accepted task permits proof insert',lx_rider_private.proof_access(object_path,'insert'));
 perform pg_temp.check_int('other actor path cannot upload proof',not lx_rider_private.proof_access(replace(object_path,'/rider1/','/rider2/'),'insert'));
 perform pg_temp.check_int('path traversal rejected',not lx_rider_private.proof_access(object_path||'/../x','insert'));
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform pg_temp.check_int('other account cannot read target proof',not lx_rider_private.proof_access(object_path,'read'));
 perform pg_temp.check_int('other account cannot insert target proof',not lx_rider_private.proof_access(object_path,'insert'));
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform pg_temp.int_cmd(u,'dispatch','expire_certificate','{"rider":"rider1"}');
 perform pg_temp.check_int('expired qualification blocks new pickup proof',not lx_rider_private.proof_access(object_path,'insert'));
 update lx_rider_private.tasks set status='picked_up' where id=ids[4];
 perform pg_temp.check_int('expired rider may upload safety handover proof',lx_rider_private.proof_access(replace(object_path,'/pickup/','/delivery/'),'insert'));
 perform pg_temp.check_int('empty photo cannot produce signed link',pg_temp.int_denied(u,'rider1','proof_link',jsonb_build_object('task_id',ids[4],'stage','delivery'),'RIDER_DOCUMENT_DENIED'));
 select count(*) into after_count from public.lx_share_bags;
 perform pg_temp.check_int('existing share bags untouched',before_count=after_count);
 perform pg_temp.check_int('proof bucket enforces private 100000-byte limit',(select not public and file_size_limit=100000 from storage.buckets where id='rider-test-proofs'));
 perform pg_temp.check_int('client still cannot execute service gateway',not has_function_privilege('authenticated','public.lx_rider_test_gateway(uuid,text,jsonb)','execute'));
end $$;
select jsonb_build_object('passed',count(*),'failed',0,'cases',jsonb_agg(name),'scope','Rollback database tests. Fixture qualification and simulated SQL claims, not Google Session, actual Storage requests, native Maps or phone acceptance.') verification from rider_int_results;
rollback;
